const requestTelemetryExistsBetween = `-- name: RequestTelemetryExistsBetween :one
SELECT EXISTS (
    SELECT 1 FROM request_telemetry
    WHERE app_id = $1
      AND received_at >= $2::timestamptz
      AND received_at <  $3::timestamptz
)::bool AS has_rows
`

